# builder/gen_ch21_p3.py
# -*- coding: utf-8 -*-

exercises = [{'num': 65, 'title': 'Спецификация однонаправленных типов: send-only и receive-only каналы', 'task': 'Создайте направленные каналы (send-only `<-chan int` и receive-only `chan<- int`) и попробуйте использовать их не по назначению. Изучите ошибки компилятора.', 'theory': 'Спецификация Go строго разграничивает типы каналов:\n* `chan<- T` (Send-only) — разрешена только операция `ch <- x` и `close(ch)`.\n* `<-chan T` (Receive-only) — разрешена только операция `<-ch` и `for x := range ch`.', 'step_by_step': '1. Создадим функцию с правильным разделением прав доступа.\n2. Продемонстрируем защиту от ошибочных действий на уровне типов.\n3. Проверим компиляцию и работу программы.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n)\n\nfunc writeOnly(out chan<- int) {\n\tout <- 42\n\t// _ = <-out // Ошибка: cannot receive from send-only channel\n\tclose(out)\n}\n\nfunc readOnly(in <-chan int) {\n\t// in <- 10  // Ошибка: cannot send to receive-only channel\n\t// close(in) // Ошибка: cannot close receive-only channel\n\tfor val := range in {\n\t\tfmt.Printf("[readOnly] Получено: %d\\n", val)\n\t}\n}\n\nfunc main() {\n\tch := make(chan int)\n\tgo writeOnly(ch)\n\treadOnly(ch)\n\tfmt.Println("Компилятор Go гарантирует корректность использования каналов!")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [readOnly] Получено: 42\n# Компилятор Go гарантирует корректность использования каналов!'}], 'under_the_hood': 'Стрелка `<-` относительно ключевого слова `chan` задает синтаксический тип во время разбора исходного кода компилятором.', 'pitfalls': 'Попытка закрыть receive-only канал `close(in)` приводит к ошибке компилятора.', 'bigtech_interview': '**Вопрос с собеседования:** «Какова совместимость типов между chan int, <-chan int и chan<- int?»\n**Ответ:** Двунаправленный `chan T` может быть неявно приведен к `<-chan T` и к `chan<- T`. Однако однонаправленные каналы не могут быть приведены к двунаправленному или друг к другу.'}, {'num': 66, 'title': 'Паттерн Debounce на базе таймера: фильтрация частых событий', 'task': 'Напиши **"debounce"** через `select` + `time.After`: при поступлении события запускай таймер. Если за время таймера пришло новое событие — сбрасывай старый таймер и запускай новый. Обработай только последнее событие в серии.', 'theory': 'Паттерн Debounce (Устранение дребезга) откладывает выполнение действия до тех пор, пока не пройдет определенный интервал «тишины» с момента последнего события (например, автодополнение поисковой строки при вводе пользователем).', 'step_by_step': '1. Создадим функцию `Debounce(in <-chan string, delay time.Duration) <-chan string`.\n2. Внутри используем `time.NewTimer` со сбросом `timer.Reset()`.\n3. Запустим быструю серию событий `"g"`, `"go"`, `"gola"`, `"golang"`.\n4. Убедимся, что на выходе обработано только последнее событие `"golang"`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"time"\n)\n\nfunc Debounce(in <-chan string, delay time.Duration) <-chan string {\n\tout := make(chan string)\n\n\tgo func() {\n\t\tdefer close(out)\n\t\tvar timer *time.Timer\n\t\tvar currentVal string\n\t\tvar timerC <-chan time.Time\n\n\t\tfor {\n\t\t\tselect {\n\t\t\tcase val, ok := <-in:\n\t\t\t\tif !ok {\n\t\t\t\t\tif timer != nil {\n\t\t\t\t\t\ttimer.Stop()\n\t\t\t\t\t}\n\t\t\t\t\treturn\n\t\t\t\t}\n\t\t\t\tcurrentVal = val\n\n\t\t\t\t// Останавливаем старый таймер и сбрасываем заново\n\t\t\t\tif timer != nil {\n\t\t\t\t\ttimer.Stop()\n\t\t\t\t}\n\t\t\t\ttimer = time.NewTimer(delay)\n\t\t\t\ttimerC = timer.C\n\n\t\t\tcase <-timerC:\n\t\t\t\tout <- currentVal\n\t\t\t\ttimerC = nil // Сбрасываем канал таймера до следующего события\n\t\t\t}\n\t\t}\n\t}()\n\n\treturn out\n}\n\nfunc main() {\n\tinput := make(chan string)\n\tdebounced := Debounce(input, 30*time.Millisecond)\n\n\tgo func() {\n\t\t// Быстрая серия ввода пользователем (с интервалом 10мс < 30мс)\n\t\tinput <- "g"\n\t\ttime.Sleep(10 * time.Millisecond)\n\t\tinput <- "go"\n\t\ttime.Sleep(10 * time.Millisecond)\n\t\tinput <- "golang" // Последнее событие\n\t\ttime.Sleep(50 * time.Millisecond)\n\t\tclose(input)\n\t}()\n\n\tfmt.Println("Результаты работы Debounce:")\n\tfor result := range debounced {\n\t\tfmt.Printf(" -> Обработано поисковое значение: %q\\n", result)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Результаты работы Debounce:\n#  -> Обработано поисковое значение: "golang" '}], 'under_the_hood': '`timer.Stop()` удаляет таймер из системного дерева таймеров рантайма, а `timer.Reset()` перезапускает отсчет.', 'pitfalls': 'Обязательно очищайте `timerC = nil`, чтобы таймер не срабатывал повторно.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем отличие Debounce от Throttle?»\n**Ответ:** Debounce ожидает паузы в потоке событий и обрабатывает **последнее** событие серии. Throttle гарантирует выполнение не чаще одного раза за период времени, обрабатывая **первое** событие и игнорируя последующие.'}, {'num': 67, 'title': 'Мультиплексор двух каналов Fan-In на цикле select', 'task': 'Мультиплексор: функция `fanIn(ch1, ch2 <-chan int) <-chan int`, сливающая два канала в один. Используйте `select` в цикле.', 'theory': 'Компактный мультиплексор объединяет два независимых асинхронных источника данных в единый канал для упрощения потребления в целевом бизнес-сервисе.', 'step_by_step': '1. Создадим `fanIn(ch1, ch2 <-chan int) <-chan int`.\n2. В цикле `select` считываем из обоих каналов.\n3. Отключаем закрытые каналы через `nil`.\n4. Закрываем выходной канал при закрытии обоих источников.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n)\n\nfunc fanIn(ch1, ch2 <-chan int) <-chan int {\n\tout := make(chan int)\n\tgo func() {\n\t\tdefer close(out)\n\t\tfor ch1 != nil || ch2 != nil {\n\t\t\tselect {\n\t\t\tcase v, ok := <-ch1:\n\t\t\t\tif !ok {\n\t\t\t\t\tch1 = nil\n\t\t\t\t\tcontinue\n\t\t\t\t}\n\t\t\t\tout <- v\n\t\t\tcase v, ok := <-ch2:\n\t\t\t\tif !ok {\n\t\t\t\t\tch2 = nil\n\t\t\t\t\tcontinue\n\t\t\t\t}\n\t\t\t\tout <- v\n\t\t\t}\n\t\t}\n\t}()\n\treturn out\n}\n\nfunc main() {\n\tsrc1 := make(chan int)\n\tsrc2 := make(chan int)\n\n\tgo func() {\n\t\tsrc1 <- 1\n\t\tsrc1 <- 2\n\t\tclose(src1)\n\t}()\n\n\tgo func() {\n\t\tsrc2 <- 10\n\t\tsrc2 <- 20\n\t\tclose(src2)\n\t}()\n\n\tcombined := fanIn(src1, src2)\n\n\tfmt.Println("Слияние потоков через fanIn:")\n\tfor item := range combined {\n\t\tfmt.Printf(" -> %d\\n", item)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Слияние потоков через fanIn:\n#  -> 1\n#  -> 10\n#  -> 2\n#  -> 20'}], 'under_the_hood': '`fanIn` объединяет события с сохранением потокобезопасности.', 'pitfalls': 'При неравномерной скорости источников `fanIn` не задерживает быстрый источник.', 'bigtech_interview': '**Вопрос с собеседования:** «Каковы свойства хорошего паттерна Fan-In?»\n**Ответ:** 1) Отсутствие блокировок между независимыми источниками. 2) Автоматическое освобождение ресурсов при закрытии входных каналов. 3) Минимальное количество переключений контекста.'}, {'num': 68, 'title': 'Антипаттерн закрытия канала получателем и паника в отправителе', 'task': 'Передай канал в функцию и закрой его *получателе* (плохая практика, но важно понимать, почему так делать не стоит — поймай панику, если отправитель попытается отправить после).', 'theory': 'Закрытие канала со стороны получателя (Receiver-side Close) — грубейший антипаттерн в Go. Если отправитель попытается записать следующее значение в закрытый получателем канал, произойдет неустранимая паника `panic: send on closed channel`.', 'step_by_step': '1. Создадим канал `ch := make(chan int)`.\n2. Запустим получателя, который считывает 1 элемент и закрывает канал `close(ch)`.\n3. Отправитель пытается записать второй элемент.\n4. Перехватим и объясним возникшую панику.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"time"\n)\n\nfunc badReceiver(ch chan int) {\n\tval := <-ch\n\tfmt.Printf("[Receiver] Прочитан элемент: %d\\n", val)\n\n\t// АНТИПАТТЕРН: Получатель закрывает канал!\n\tfmt.Println("[Receiver] Закрываю канал со стороны получателя...")\n\tclose(ch)\n}\n\nfunc sender(ch chan int) {\n\tch <- 100 // Успешно\n\n\ttime.Sleep(10 * time.Millisecond)\n\n\t// Защита от паники\n\tdefer func() {\n\t\tif r := recover(); r != nil {\n\t\t\tfmt.Printf("[Sender] АВАРИЯ: Отправитель поймал панику: %v\\n", r)\n\t\t}\n\t}()\n\n\tfmt.Println("[Sender] Попытка отправки второго числа 200...")\n\tch <- 200 // ВЫЗЫВАЕТ ПАНИКУ: send on closed channel\n}\n\nfunc main() {\n\tch := make(chan int)\n\n\tgo badReceiver(ch)\n\tsender(ch)\n\n\tfmt.Println("\\nВывод: Канал ВСЕГДА должен закрываться ТОЛЬКО отправителем!")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Receiver] Прочитан элемент: 100\n# [Receiver] Закрываю канал со стороны получателя...\n# [Sender] Попытка отправки второго числа 200...\n# [Sender] АВАРИЯ: Отправитель поймал панику: send on closed channel\n# \n# Вывод: Канал ВСЕГДА должен закрываться ТОЛЬКО отправителем!'}], 'under_the_hood': '`runtime.chansend` при проверке `c.closed != 0` паникует, так как запись в закрытый канал нарушает фундаментальный контракт целостности.', 'pitfalls': 'Никогда не закрывайте канал в функции, принимающей `<-chan T`.', 'bigtech_interview': '**Вопрос с собеседования:** «Каковы золотые правила владения каналами (Channel Ownership) в Go?»\n**Ответ:** Горутина, которая создает канал, является его владельцем. Только владелец имеет право: 1) Инициализировать канал, 2) Записывать в него данные, 3) Закрывать канал. Получатели имеют право только читать из канала.'}, {'num': 69, 'title': 'Паттерн Throttle: ограничение частоты пропускания событий', 'task': 'Напиши **"throttle"** : пропускай события не чаще, чем раз в N миллисекунд. Если событие пришло раньше — игнорируй (или буферизуй одно). Используй `select` с `time.After`.', 'theory': 'Паттерн Throttle (Дросселирование) гарантирует, что события пропускаются дальше с частотой не более одного раза в $N$ миллисекунд, отбрасывая промежуточный спам (например, скролл страницы или нажатие кнопки отправки формы).', 'step_by_step': '1. Создадим функцию `Throttle(in <-chan int, interval time.Duration) <-chan int`.\n2. Пропускаем первое событие и запускаем защитный интервал.\n3. Все последующие события во время интервала отбрасываем.\n4. Проверим пропуск пачки из 5 частых событий.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"time"\n)\n\nfunc Throttle(in <-chan int, interval time.Duration) <-chan int {\n\tout := make(chan int)\n\n\tgo func() {\n\t\tdefer close(out)\n\t\tvar lastEmit time.Time\n\n\t\tfor val := range in {\n\t\t\tnow := time.Now()\n\t\t\tif now.Sub(lastEmit) >= interval {\n\t\t\t\tout <- val\n\t\t\t\tlastEmit = now\n\t\t\t} else {\n\t\t\t\tfmt.Printf("[Throttle] Событие #%d отброшено (слишком часто)\\n", val)\n\t\t\t}\n\t\t}\n\t}()\n\n\treturn out\n}\n\nfunc main() {\n\tevents := make(chan int)\n\tthrottled := Throttle(events, 25*time.Millisecond)\n\n\tgo func() {\n\t\t// Отправляем 4 быстрых события с интервалом 5 мс\n\t\tfor i := 1; i <= 4; i++ {\n\t\t\tevents <- i\n\t\t\ttime.Sleep(5 * time.Millisecond)\n\t\t}\n\t\t// Ждем 30 мс (интервал тишины)\n\t\ttime.Sleep(30 * time.Millisecond)\n\t\tevents <- 5 // Это событие должно пройти\n\t\tclose(events)\n\t}()\n\n\tfmt.Println("Пропущенные через Throttle события:")\n\tfor res := range throttled {\n\t\tfmt.Printf(" -> Успешно пропущено событие: %d\\n", res)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Throttle] Событие #2 отброшено (слишком часто)\n# [Throttle] Событие #3 отброшено (слишком часто)\n# [Throttle] Событие #4 отброшено (слишком часто)\n# Пропущенные через Throttle события:\n#  -> Успешно пропущено событие: 1\n#  -> Успешно пропущено событие: 5'}], 'under_the_hood': '`Throttle` использует временные метки `time.Now()` и `time.Sub()` для $O(1)$ фильтрации потока.', 'pitfalls': 'Не блокируйте входящий канал — входящие события должны быстро считываться и отбрасываться.', 'bigtech_interview': '**Вопрос с собеседования:** «Как реализовать Throttle с сохранением самого последнего значения (Trailing Throttle)?»\n**Ответ:** При поступлении событий во время защитного интервала сохранять последнее значение в локальную переменную и по таймеру отправлять его в выходной канал.'}, {'num': 70, 'title': 'Инкапсуляция генератора чисел с передачей send-only канала', 'task': 'Напишите функцию, которая принимает канал для записи, генерирует числа и закрывает канал по завершении.', 'theory': 'Прием канала для записи `out chan<- int` позволяет вызывающему коду самому контролировать создание и размер буфера канала.', 'step_by_step': '1. Создадим функцию `PopulateChannel(out chan<- int, count int)`.\n2. Внутри сгенерируем числа и вызовем `close(out)`.\n3. В `main` создадим буферизованный канал и передадим его в функцию.\n4. Вычитаем данные.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n)\n\nfunc PopulateChannel(out chan<- int, count int) {\n\tdefer close(out)\n\tfor i := 1; i <= count; i++ {\n\t\tout <- i * 10\n\t}\n}\n\nfunc main() {\n\tch := make(chan int, 3)\n\n\tgo PopulateChannel(ch, 3)\n\n\tfmt.Println("Чтение сгенерированных элементов:")\n\tfor item := range ch {\n\t\tfmt.Printf(" -> Элемент: %d\\n", item)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Чтение сгенерированных элементов:\n#  -> Элемент: 10\n#  -> Элемент: 20\n#  -> Элемент: 30'}], 'under_the_hood': '`defer close(out)` выполняется даже при панике внутри генератора.', 'pitfalls': 'Не вызывайте `PopulateChannel` на одном канале из нескольких горутин без `sync.WaitGroup`, иначе возникнет паника двойного закрытия.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем отличие генератора, возвращающего канал, от генератора, принимающего канал?»\n**Ответ:** Возвращающий канал генератор инкапсулирует создание горутины и размер буфера внутри себя. Принимающий канал генератор дает вызывающему коду полный контроль над аллокацией канала и его буферизацией.'}, {'num': 71, 'title': 'Graceful Shutdown микросервиса по системным сигналам OS (SIGINT/SIGTERM)', 'task': 'Напиши **"graceful shutdown"**: `select` между рабочим каналом и `os.Signal` каналом (`signal.Notify`). При получении `os.Interrupt` — закрой рабочий канал, дождись `sync.WaitGroup`, выведи `"shutting down gracefully"`.', 'theory': 'Корректное завершение (Graceful Shutdown) перехватывает системные сигналы ядра Linux (`SIGINT` Ctrl+C, `SIGTERM` Kubernetes pod termination) через `os/signal.Notify` и дает сервису время завершить текущие запросы перед остановкой.', 'step_by_step': '1. Создадим буферизованный канал сигналов `sigChan := make(chan os.Signal, 1)`.\n2. Зарегистрируем перехват `signal.Notify(sigChan, os.Interrupt)`.\n3. В воркере слушаем задачи и сигнал отмены.\n4. Продемонстрируем имитацию сигнала остановки.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"os"\n\t"sync"\n\t"time"\n)\n\nfunc worker(id int, stopChan <-chan struct{}, wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\tfmt.Printf("[Worker #%d] Запущен и обрабатывает фоновые задачи...\\n", id)\n\n\tfor {\n\t\tselect {\n\t\tcase <-stopChan:\n\t\t\tfmt.Printf("[Worker #%d] Получен сигнал STOP -> корректное завершение\\n", id)\n\t\t\treturn\n\t\tdefault:\n\t\t\ttime.Sleep(10 * time.Millisecond)\n\t\t}\n\t}\n}\n\nfunc main() {\n\t// Канал сигналов ОС ВСЕГДА должен иметь буфер >= 1\n\tsigChan := make(chan os.Signal, 1)\n\tstopWorkers := make(chan struct{})\n\n\tvar wg sync.WaitGroup\n\tconst totalWorkers = 2\n\n\tfor i := 1; i <= totalWorkers; i++ {\n\t\twg.Add(1)\n\t\tgo worker(i, stopWorkers, &wg)\n\t}\n\n\t// Имитация прихода сигнала SIGINT через 25 мс\n\tgo func() {\n\t\ttime.Sleep(25 * time.Millisecond)\n\t\tsigChan <- os.Interrupt\n\t}()\n\n\t// Главный поток ожидает системный сигнал\n\t<-sigChan\n\tfmt.Println("\\n[Main] Получен сигнал os.Interrupt! Инициирую Graceful Shutdown...")\n\n\tclose(stopWorkers) // Уведомляем всех воркеров\n\twg.Wait()          // Дожидаемся завершения\n\n\tfmt.Println("[Main] shutting down gracefully: Все ресурсы освобождены, выход.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Worker #1] Запущен и обрабатывает фоновые задачи...\n# [Worker #2] Запущен и обрабатывает фоновые задачи...\n# \n# [Main] Получен сигнал os.Interrupt! Инициирую Graceful Shutdown...\n# [Worker #1] Получен сигнал STOP -> корректное завершение\n# [Worker #2] Получен сигнал STOP -> корректное завершение\n# [Main] shutting down gracefully: Все ресурсы освобождены, выход.'}], 'under_the_hood': '`signal.Notify` перехватывает сигналы POSIX и перенаправляет их в Go-канал через синглтон-обработчик рантайма.', 'pitfalls': 'Канал для `signal.Notify` обязан иметь буфер емкостью как минимум 1 (`make(chan os.Signal, 1)`), иначе сигнал ОС будет потерян, если горутина не успела встать на чтение.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему канал для signal.Notify обязан быть буферизованным?»\n**Ответ:** Потому что рантайм Go отправляет сигналы ОС неблокирующим вызовом (Non-blocking Send). Если канал небуферизован и горутина не стоит в `<-sigChan` в этот точный момент, сигнал будет безвозвратно утерян.'}, {'num': 72, 'title': 'Паттерн Futures / Promises в Go на базе однократного канала', 'task': 'Передайте канал в качестве аргумента функции для возврата результата (паттерн "Futures" / "Promises").', 'theory': 'Паттерн Future / Promise (Обещание) представляет собой дескриптор результата асинхронного вычисления. В Go объект Future реализуется обычным каналом `<-chan Result`, куда горутина единожды записывает результат.', 'step_by_step': '1. Создадим структуру `Future[T any]`.\n2. Реализуем функцию `AsyncExec[T](fn func() T) <-chan T`.\n3. Запустим асинхронную операцию.\n4. Вычитаем результат в нужный момент.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"time"\n)\n\n// Асинхронный запуск вычисления с возвратом Future (канала)\nfunc AsyncCompute(a, b int) <-chan int {\n\tfuture := make(chan int, 1)\n\tgo func() {\n\t\ttime.Sleep(20 * time.Millisecond) // Симуляция тяжелых вычислений\n\t\tfuture <- a * b\n\t}()\n\treturn future\n}\n\nfunc main() {\n\tfmt.Println("[Main] Запуск асинхронной задачи (Promise)...")\n\tpromise := AsyncCompute(6, 7)\n\n\tfmt.Println("[Main] Выполняю другие независимые операции...")\n\ttime.Sleep(10 * time.Millisecond)\n\n\tfmt.Println("[Main] Ожидание разрешения Promise (<-promise)...")\n\tresult := <-promise\n\n\tfmt.Printf("[Main] Результат успешно получен из Future: %d\\n", result)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Main] Запуск асинхронной задачи (Promise)...\n# [Main] Выполняю другие независимые операции...\n# [Main] Ожидание разрешения Promise (<-promise)...\n# [Main] Результат успешно получен из Future: 42'}], 'under_the_hood': '`<-promise` блокирует поток только в том случае, если вычисление еще не завершилось.', 'pitfalls': 'Используйте буфер емкостью 1 (`make(chan T, 1)`), чтобы горутина вычисления не зависла при досрочном отказе от ожидания результата.', 'bigtech_interview': '**Вопрос с собеседования:** «Чем Future в Go отличается от std::future в C++ или Promise в JS?»\n**Ответ:** В Go нет отдельного класса `Future` — его роль выполняет обычный канал `<-chan T`, что позволяет мультиплексировать несколько фьючерсов через стандартный `select` без дополнительных библиотек.'}, {'num': 73, 'title': 'Динамическое выключение веток в select через обнуление канала (nil channel)', 'task': 'Напиши программу с `select` и **nil каналом**: динамически "выключай" case, присваивая каналу `nil`. Покажи, что case с nil каналом **никогда не выбирается** (это способ временно отключить case).', 'theory': 'Присваивание переменной канала значения `nil` (`ch = nil`) мгновенно и обратимо выключает соответствующую ветку `case` в конструкции `select`.', 'step_by_step': '1. Создадим два канала `ch1` и `ch2`.\n2. Заполним оба канала данными.\n3. Прочитав из `ch1`, присвоим `ch1 = nil`.\n4. Убедимся, что на следующей итерации выбирается только `ch2`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n)\n\nfunc main() {\n\tch1 := make(chan string, 1)\n\tch2 := make(chan string, 1)\n\n\tch1 <- "Сообщение из канала 1"\n\tch2 <- "Сообщение из канала 2"\n\n\t// Итерация 1: Отключаем канал 1 после первого чтения\n\tfor i := 0; i < 2; i++ {\n\t\tselect {\n\t\tcase msg, ok := <-ch1:\n\t\t\tif ok {\n\t\t\t\tfmt.Printf("1. Получено из ch1: %q -> отключаем ветку ch1 (ch1 = nil)\\n", msg)\n\t\t\t\tch1 = nil // Динамическое отключение ветки!\n\t\t\t}\n\t\tcase msg, ok := <-ch2:\n\t\t\tif ok {\n\t\t\t\tfmt.Printf("2. Получено из ch2: %q -> отключаем ветку ch2 (ch2 = nil)\\n", msg)\n\t\t\t\tch2 = nil\n\t\t\t}\n\t\t}\n\t}\n\n\tfmt.Println("Оба канала успешно обработаны и отключены.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# 1. Получено из ch1: "Сообщение из канала 1" -> отключаем ветку ch1 (ch1 = nil)\n# 2. Получено из ch2: "Сообщение из канала 2" -> отключаем ветку ch2 (ch2 = nil)\n# Оба канала успешно обработаны и отключены.'}], 'under_the_hood': '`nil`-канал игнорируется рантаймом `selectgo` на уровне проверки дескрипторов.', 'pitfalls': 'Если все каналы в `select` станут `nil`, горутина заснет навсегда (дедлок).', 'bigtech_interview': '**Вопрос с собеседования:** «Как временно приостановить чтение из канала в select при превышении локального лимита?»\n**Ответ:** Сохранить указатель на канал во временную переменную `saved := ch; ch = nil`. После спада нагрузки восстановить чтение `ch = saved`.'}, {'num': 74, 'title': 'Периодическая генерация событий: time.Tick и завершение по таймауту', 'task': 'Тикер: каждые 500 мс отправлять в канал `time.Tick`, основная горутина читает и выводит «tick», пока не истечёт таймаут.', 'theory': '`time.Tick(d)` возвращает канал, в который рантайм периодически отправляет метки времени `time.Time`.', 'step_by_step': '1. Создадим канал тиков `ticker := time.Tick(15 * time.Millisecond)`.\n2. Создадим канал завершения `timeout := time.After(50 * time.Millisecond)`.\n3. В цикле `select` считываем тики.\n4. По истечении таймаута штатно выходим.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"time"\n)\n\nfunc main() {\n\ttickChan := time.Tick(15 * time.Millisecond)\n\ttimeoutChan := time.After(50 * time.Millisecond)\n\n\tfmt.Println("Старт периодического опроса:")\n\tcount := 0\n\n\tfor {\n\t\tselect {\n\t\tcase t := <-tickChan:\n\t\t\tcount++\n\t\t\tfmt.Printf(" [Tick #%d] Сработал тик в %s\\n", count, t.Format("15:04:05.000"))\n\t\tcase <-timeoutChan:\n\t\t\tfmt.Println("Общий таймаут истек! Завершение цикла тиков.")\n\t\t\treturn\n\t\t}\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Старт периодического опроса:\n#  [Tick #1] Сработал тик в 15:04:05.015\n#  [Tick #2] Сработал тик в 15:04:05.030\n#  [Tick #3] Сработал тик в 15:04:05.045\n# Общий таймаут истек! Завершение цикла тиков.'}], 'under_the_hood': '`time.Tick` оборачивает `time.NewTicker`, но не экспортирует метод `Stop()`.', 'pitfalls': 'Никогда не используйте `time.Tick` внутри долгоживущих методов и хендлеров, так как лежащий в его основе тикер невозможно остановить (утечка памяти). Используйте `time.NewTicker`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему официальная документация Go не рекомендует использовать time.Tick в большинстве случаев?»\n**Ответ:** Потому что `time.Tick` не возвращает объект тикера и не предоставляет метод `Stop()`. Созданный тикер и его горутина никогда не удаляются сборщиком мусора, вызывая постоянную утечку памяти при многократных вызовах.'}, {'num': 75, 'title': 'Бесконечный мультиплексор событий: цикл for select', 'task': '**`select` в цикле**: Помести `select` в бесконечный `for { select { ... } }`, чтобы читать из нескольких каналов непрерывно.', 'theory': 'Конструкция `for { select { ... } }` (Event Loop) — основной архитектурный каркас для микросервисов, акторов, диспетчеров очередей и сетевых серверов в Go.', 'step_by_step': '1. Создадим два канала событий `metrics` и `alerts`.\n2. Запустим диспетчер событий `for { select { ... } }`.\n3. Отправим серию метрик и алертов.\n4. Завершим работу по сигналу остановки.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"time"\n)\n\nfunc main() {\n\tmetrics := make(chan string, 3)\n\talerts := make(chan string, 3)\n\tstop := make(chan struct{})\n\n\t// Фоновый диспетчер (Event Loop)\n\tgo func() {\n\t\tfor {\n\t\t\tselect {\n\t\t\tcase m := <-metrics:\n\t\t\t\tfmt.Printf("[METRIC] %s\\n", m)\n\t\t\tcase a := <-alerts:\n\t\t\t\tfmt.Printf("[ALERT]  %s\\n", a)\n\t\t\tcase <-stop:\n\t\t\t\tfmt.Println("[EventLoop] Получен сигнал остановки, выход.")\n\t\t\t\treturn\n\t\t\t}\n\t\t}\n\t}()\n\n\tmetrics <- "cpu_usage = 42%"\n\talerts <- "disk_space_low /dev/sda1"\n\tmetrics <- "memory_usage = 68%"\n\n\ttime.Sleep(20 * time.Millisecond)\n\tclose(stop)\n\ttime.Sleep(10 * time.Millisecond)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [METRIC] cpu_usage = 42%\n# [ALERT]  disk_space_low /dev/sda1\n# [METRIC] memory_usage = 68%\n# [EventLoop] Получен сигнал остановки, выход.'}], 'under_the_hood': 'Планировщик эффективно переключает контекст между горутинами событий.', 'pitfalls': 'Всегда предусматривайте ветку завершения `case <-ctx.Done():` или `case <-stop:`.', 'bigtech_interview': '**Вопрос с собеседования:** «Как избежать дедлока при закрытии диспетчера for select?»\n**Ответ:** Закрывать сигнальный канал `stop` и дожидаться завершения диспетчера через `sync.WaitGroup`.'}, {'num': 76, 'title': 'Эмуляция алгоритма Round-Robin через динамические nil-каналы', 'task': 'Напиши **"round-robin"** через `select`: три канала-источника. Используй `select` в цикле, но после чтения из канала A — временно "отключай" его (nil) на одну итерацию, чтобы дать возможность B и C. Обсуди, почему это сложно сделать чисто через select.', 'theory': 'Спецификация `select` в Go намеренно псевдослучайна. Для реализации строгого циклического опроса (Round-Robin $A \\to B \\to C$) прочитанный канал временно выключают (`ch = nil`), пока не будут прочитаны остальные источники.', 'step_by_step': '1. Создадим три канала `chA`, `chB`, `chC` с буфером 1.\n2. Заполним все три канала.\n3. Реализуем ротацию каналов через переменные состояния.\n4. Продемонстрируем строгую очередность вычитывания.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n)\n\nfunc main() {\n\tchA := make(chan string, 1)\n\tchB := make(chan string, 1)\n\tchC := make(chan string, 1)\n\n\tchA <- "A1"\n\tchB <- "B1"\n\tchC <- "C1"\n\n\tcurA, curB, curC := chA, chB, chC\n\n\tfmt.Println("Round-Robin вычитывание из 3 каналов:")\n\tfor i := 0; i < 3; i++ {\n\t\tselect {\n\t\tcase msg := <-curA:\n\t\t\tfmt.Printf(" -> Источник %s\\n", msg)\n\t\t\tcurA = nil // Отключаем A до следующего полного круга\n\t\tcase msg := <-curB:\n\t\t\tfmt.Printf(" -> Источник %s\\n", msg)\n\t\t\tcurB = nil // Отключаем B\n\t\tcase msg := <-curC:\n\t\t\tfmt.Printf(" -> Источник %s\\n", msg)\n\t\t\tcurC = nil // Отключаем C\n\t\t}\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Round-Robin вычитывание из 3 каналов:\n#  -> Источник A1\n#  -> Источник B1\n#  -> Источник C1'}], 'under_the_hood': 'Динамическая замена `curA = nil` гарантирует, что `select` на следующем шаге выбирает только из оставшихся активных каналов.', 'pitfalls': 'Для $N > 5$ каналов управление nil-переменными в `select` становится громоздким. В таких случаях используют кольцевую очередь срезов `[]chan T`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в Go нет встроенного оператора Round-Robin для каналов?»\n**Ответ:** Потому что псевдослучайный выбор (Random Uniform) в `select` обеспечивает математически доказанную защиту от взаимных блокировок и голодания без сохранения тяжелого состояния ротации в заголовках каналов.'}, {'num': 77, 'title': 'Сравнительный бенчмарк: Передача по каналу против sync.Mutex', 'task': 'Сравните скорость передачи данных через канал и через глобальную переменную с `sync.Mutex`.', 'theory': 'Инженерное сравнение:\n* `sync.Mutex` быстрее для простых ин-мемори мутаций счетчиков и структур на 1 ядре CPU (~15–25 ns).\n* Каналы (CSP) обеспечивают безопасную передачу владения (Transfer of Ownership) данными между горутинами без гонок данных и без риска блокировки структур в чужих функциях (~50–80 ns).', 'step_by_step': '1. Напишем сводный тест производительности 100 000 операций.\n2. Замерим время работы через буферизованный канал.\n3. Замерим время работы через `sync.Mutex`.\n4. Сформулируем выводы.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\nfunc main() {\n\tconst totalOps = 100000\n\n\t// 1. Тест с каналом\n\tch := make(chan int, 100)\n\tstart := time.Now()\n\tgo func() {\n\t\tfor i := 0; i < totalOps; i++ {\n\t\t\tch <- i\n\t\t}\n\t\tclose(ch)\n\t}()\n\n\tfor range ch {\n\t}\n\tchanDuration := time.Since(start)\n\n\t// 2. Тест с sync.Mutex\n\tvar mu sync.Mutex\n\tcounter := 0\n\tstart = time.Now()\n\tfor i := 0; i < totalOps; i++ {\n\t\tmu.Lock()\n\t\tcounter++\n\t\tmu.Unlock()\n\t}\n\tmutexDuration := time.Since(start)\n\n\tfmt.Printf("1. Передача через канал: %v (100k операций)\\n", chanDuration)\n\tfmt.Printf("2. Защита через Mutex:   %v (100k операций)\\n", mutexDuration)\n\tfmt.Println("\\nВывод: Mutex быстрее для локальных счетчиков, каналы лучше для координации и очередей задач.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# 1. Передача через канал: 4.85ms (100k операций)\n# 2. Защита через Mutex:   1.75ms (100k операций)\n# \n# Вывод: Mutex быстрее для локальных счетчиков, каналы лучше для координации и очередей задач.'}], 'under_the_hood': 'Канал внутри использует собственный мьютекс `hchan.lock` плюс управление кольцевым буфером, поэтому элементарная операция с каналом чуть медленнее прямого мьютекса.', 'pitfalls': 'Не оптимизируйте код преждевременно: в 90% случаев читаемость и надежность каналов важнее разницы в единицы наносекунд.', 'bigtech_interview': '**Вопрос с собеседования:** «Каков девиз Go относительно разделяемой памяти и каналов?»\n**Ответ:** «Do not communicate by sharing memory; instead, share memory by communicating» (Не общайтесь через разделяемую память; вместо этого разделяйте память через общение по каналам).'}, {'num': 78, 'title': 'Неблокирующее чтение из канала через select с веткой default', 'task': 'Используй `default` в `select`, чтобы сделать неблокирующее чтение из канала (если данных нет, select сразу переходит к `default`).', 'theory': 'Конструкция `select` с веткой `default` выполняет мгновенную проверку наличия элементов в канале.', 'step_by_step': '1. Создадим канал `inbox := make(chan string, 1)`.\n2. Проверим неблокирующее чтение из пустого канала.\n3. Добавим сообщение и проверим успешное чтение.\n4. Выведем результаты.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n)\n\nfunc main() {\n\tinbox := make(chan string, 1)\n\n\t// Чтение 1: канал пуст\n\tselect {\n\tcase mail := <-inbox:\n\t\tfmt.Printf("Получено письмо: %s\\n", mail)\n\tdefault:\n\t\tfmt.Println("1. Почтовый ящик пуст (немедленный переход в default)")\n\t}\n\n\tinbox <- "Срочный отчет"\n\n\t// Чтение 2: канал содержит элемент\n\tselect {\n\tcase mail := <-inbox:\n\t\tfmt.Printf("2. Успешно прочитано: %q\\n", mail)\n\tdefault:\n\t\tfmt.Println("Почтовый ящик пуст")\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# 1. Почтовый ящик пуст (немедленный переход в default)\n# 2. Успешно прочитано: "Срочный отчет" '}], 'under_the_hood': '`select` не переводит горутину в спящий режим `_Gwaiting`.', 'pitfalls': 'В ветке `default` нельзя выполнять долгие блокирующие вызовы I/O.', 'bigtech_interview': '**Вопрос с собеседования:** «Как проверить, пуст ли канал, не читая из него значение?»\n**Ответ:** Проверить `len(ch) == 0` (для буферизованных каналов), однако в многопоточной среде состояние канала может измениться в следующий такт времени, поэтому идиоматично использовать `select` с `default`.'}, {'num': 79, 'title': 'Мгновенное выполнение default при неготовности всех каналов', 'task': '**Non-blocking чтение**: В `select` добавь ветку `default`. Убедись, что если ни один канал не готов, мгновенно срабатывает `default`, и программа не блокируется.', 'theory': 'Ветка `default` имеет наивысший приоритет исполнения **только тогда**, когда ни один из указанных `case` не готов к немедленному обмену данными.', 'step_by_step': '1. Создадим два небуферизованных канала `a` и `b`.\n2. Выполним `select` над обоими каналами с веткой `default`.\n3. Убедимся, что выполнение занимает 0 миллисекунд.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"time"\n)\n\nfunc main() {\n\tchA := make(chan int)\n\tchB := make(chan int)\n\n\tstart := time.Now()\n\n\t// Ни один канал не готов -> мгновенно сработает default\n\tselect {\n\tcase v := <-chA:\n\t\tfmt.Printf("Получено из A: %d\\n", v)\n\tcase v := <-chB:\n\t\tfmt.Printf("Получено из B: %d\\n", v)\n\tdefault:\n\t\tfmt.Println("Ни один канал не готов! Мгновенный выход в ветку default.")\n\t}\n\n\tfmt.Printf("Время выполнения проверки: %v\\n", time.Since(start))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Ни один канал не готов! Мгновенный выход в ветку default.\n# Время выполнения проверки: 2.1µs'}], 'under_the_hood': 'Рантайм проверяет флаги блокировки всех дескрипторов за микросекунды.', 'pitfalls': 'Не забывайте, что если хотя бы один канал готов, ветка `default` игнорируется.', 'bigtech_interview': '**Вопрос с собеседования:** «Может ли ветка default выполниться, если в одном из каналов есть готовые данные?»\n**Ответ:** Нет! Спецификация Go гарантирует, что ветка `default` выполняется только в том случае, если ни один из каналов не готов к неблокирующей операции.'}, {'num': 80, 'title': 'Синхронное ожидание данных из двух параллельных каналов через select', 'task': 'Используйте `select` для ожидания данных из двух разных каналов одновременно.', 'theory': 'Ожидание первого готового ответа от нескольких параллельных источников (Hedged Requests / First-Result Pattern).', 'step_by_step': '1. Создадим каналы от двух реплик БД `replica1` и `replica2`.\n2. Запустим горутины с разной задержкой ответа.\n3. В `select` дождемся первого готового ответа.\n4. Напечатаем результат.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"time"\n)\n\nfunc queryReplica(name string, delay time.Duration) <-chan string {\n\tout := make(chan string, 1)\n\tgo func() {\n\t\ttime.Sleep(delay)\n\t\tout <- fmt.Sprintf("Данные от %s (задержка %v)", name, delay)\n\t}()\n\treturn out\n}\n\nfunc main() {\n\tr1 := queryReplica("Реплика Восток", 40*time.Millisecond)\n\tr2 := queryReplica("Реплика Запад", 15*time.Millisecond)\n\n\tfmt.Println("Ожидание первого ответа из двух реплик...")\n\n\tselect {\n\tcase res := <-r1:\n\t\tfmt.Printf("Быстрее ответила: %s\\n", res)\n\tcase res := <-r2:\n\t\tfmt.Printf("Быстрее ответила: %s\\n", res)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Ожидание первого ответа из двух реплик...\n# Быстрее ответила: Данные от Реплика Запад (задержка 15ms)'}], 'under_the_hood': '`select` усыпляет горутину и просыпается по первому сигналу от Реплики Запад.', 'pitfalls': 'Используйте буфер емкостью 1 в `queryReplica`, чтобы вторая, более медленная реплика не зависла в памяти после выхода `select`.', 'bigtech_interview': '**Вопрос с собеседования:** «Как паттерн Hedged Requests на select снижает 99-й перцентиль задержки (p99 latency)?»\n**Ответ:** Отправляя один и тот же запрос параллельно в 2 реплики и забирая первый через `select`, система нивелирует случайные задержки на GC или сетевые лаги одной из нод.'}, {'num': 81, 'title': 'Контроль таймаута операций через case <-time.After() в select', 'task': '**Таймаут через `select`**: Добавь в `select` case: `case <-time.After(2 * time.Second):`. Убедись, что если данные не приходят 2 секунды, срабатывает этот таймаут.', 'theory': 'Шаблон таймаута на `time.After()` гарантирует верхнюю границу ожидания для любой синхронной операции.', 'step_by_step': '1. Создадим канал `data := make(chan int)`.\n2. Запустим `select` с ожиданием данных или таймаута 30 мс.\n3. Продемонстрируем безопасный выход.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"time"\n)\n\nfunc main() {\n\tdata := make(chan int)\n\n\tfmt.Println("[Client] Ожидание поступления данных с таймаутом 30мс...")\n\n\tselect {\n\tcase val := <-data:\n\t\tfmt.Printf("[Client] Успешно получены данные: %d\\n", val)\n\tcase <-time.After(30 * time.Millisecond):\n\t\tfmt.Println("[Client] ТАЙМАУТ: Данные не поступили в течение 30мс -> безопасный выход!")\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Client] Ожидание поступления данных с таймаутом 30мс...\n# [Client] ТАЙМАУТ: Данные не поступили в течение 30мс -> безопасный выход!'}], 'under_the_hood': '`time.After` запускает таймер в фоновом рантайме таймеров Go.', 'pitfalls': 'Не забывайте, что таймер создается заново при каждом вызове `time.After()`.', 'bigtech_interview': '**Вопрос с собеседования:** «Что происходит с каналом time.After, если данные из рабочего канала пришли раньше таймаута?»\n**Ответ:** Рабочая ветка успешно отрабатывает, но канал таймера и его внутренний объект `runtime.timer` остаются в памяти до фактического истечения времени таймаута, после чего собираются GC.'}, {'num': 82, 'title': 'Неблокирующая отправка и чтение данных (Non-blocking Channel Operations)', 'task': 'Добавьте `default` в `select`, чтобы реализовать неблокирующее чтение/запись (non-blocking channel operations).', 'theory': 'Комплексный практикум: реализация неблокирующего чтения (`TryReceive`) и неблокирующей отправки (`TrySend`) на базе конструкции `select default`.', 'step_by_step': '1. Реализуем функцию `TrySend[T](ch chan<- T, val T) bool`.\n2. Реализуем функцию `TryReceive[T](ch <-chan T) (T, bool)`.\n3. Протестируем на буфере емкостью 1.\n4. Проверим логику.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n)\n\nfunc TrySend[T any](ch chan<- T, val T) bool {\n\tselect {\n\tcase ch <- val:\n\t\treturn true\n\tdefault:\n\t\treturn false\n\t}\n}\n\nfunc TryReceive[T any](ch <-chan T) (T, bool) {\n\tvar zero T\n\tselect {\n\tcase val, ok := <-ch:\n\t\treturn val, ok\n\tdefault:\n\t\treturn zero, false\n\t}\n}\n\nfunc main() {\n\tch := make(chan string, 1)\n\n\t// 1. Неблокирующая запись в свободный буфер\n\tsent1 := TrySend(ch, "Message #1")\n\tfmt.Printf("1. TrySend #1: отправлено = %v\\n", sent1)\n\n\t// 2. Неблокирующая запись в заполненный буфер\n\tsent2 := TrySend(ch, "Message #2")\n\tfmt.Printf("2. TrySend #2: отправлено = %v (буфер полон, запись отброшена)\\n", sent2)\n\n\t// 3. Неблокирующее чтение\n\tval, ok := TryReceive(ch)\n\tfmt.Printf("3. TryReceive: val=%q, ok=%v\\n", val, ok)\n\n\t// 4. Повторное неблокирующее чтение из пустого буфера\n\tval, ok = TryReceive(ch)\n\tfmt.Printf("4. TryReceive: val=%q, ok=%v (канал пуст!)\\n", val, ok)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# 1. TrySend #1: отправлено = true\n# 2. TrySend #2: отправлено = false (буфер полон, запись отброшена)\n# 3. TryReceive: val="Message #1", ok=true\n# 4. TryReceive: val="", ok=false (канал пуст!)'}], 'under_the_hood': 'Дженерик-функции `TrySend` и `TryReceive` компилируются в оптимизированный байткод проверки состояния `hchan`.', 'pitfalls': 'Не применяйте `TrySend` к небуферизованному каналу, если читатель не стоит в `recvq` в этот точный момент.', 'bigtech_interview': '**Вопрос с собеседования:** «Когда функция TrySend на небуферизованном канале вернет true?»\n**Ответ:** Строго в том случае, если в этот самый момент на канале уже заблокирована и ожидает горутина-получатель (`hchan.recvq != nil`).'}, {'num': 83, 'title': 'Ловушка утечки памяти с time.After в цикле select и рефакторинг на time.NewTimer', 'task': '**Каверзный `time.After` в цикле**: Напиши `for` с `select`, внутри которого есть `case <-time.After(...)`. Изучи (в теории или профилировщиком), почему это вызывает **утечку памяти** (на каждой итерации создается новый таймер, который висит в памяти до срабатывания). Вынеси `time.NewTimer` перед циклом.', 'theory': 'Критическая архитектурная ловушка: вызов `time.After(5 * time.Minute)` внутри частого цикла `for select` создает новый объект `runtime.timer` на каждой итерации. Если сообщения поступают каждые 10 мс, за 5 минут создается $30\\,000$ таймеров, которые не могут быть удалены сборщиком мусора до их срабатывания! Решение — создание единого `time.NewTimer` перед циклом со сбросом `timer.Reset()`.', 'step_by_step': '1. Создадим поток частых сообщений `stream := make(chan int)`.\n2. Создадим один таймер перед циклом: `timer := time.NewTimer(timeout)`.\n3. На каждой итерации сбрасываем таймер через `timer.Reset()`.\n4. Убедимся в отсутствии утечки таймеров.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"time"\n)\n\nfunc main() {\n\tstream := make(chan int)\n\n\t// Продюсер шлет 4 быстрых сообщения\n\tgo func() {\n\t\tfor i := 1; i <= 4; i++ {\n\t\t\ttime.Sleep(10 * time.Millisecond)\n\t\t\tstream <- i\n\t\t}\n\t\tclose(stream)\n\t}()\n\n\tconst idleTimeout = 50 * time.Millisecond\n\n\t// ПРАВИЛЬНОЕ РЕШЕНИЕ: один таймер перед циклом\n\ttimer := time.NewTimer(idleTimeout)\n\tdefer timer.Stop()\n\n\tfmt.Println("Обработка потока с защитой от утечек таймеров:")\n\n\tfor {\n\t\t// Сбрасываем существующий таймер перед каждой итерацией\n\t\tif !timer.Stop() {\n\t\t\tselect {\n\t\t\tcase <-timer.C:\n\t\t\tdefault:\n\t\t\t}\n\t\t}\n\t\ttimer.Reset(idleTimeout)\n\n\t\tselect {\n\t\tcase val, ok := <-stream:\n\t\t\tif !ok {\n\t\t\t\tfmt.Println("Поток успешно завершен!")\n\t\t\t\treturn\n\t\t\t}\n\t\t\tfmt.Printf(" -> Обработан элемент: %d (таймер сброшен)\\n", val)\n\n\t\tcase <-timer.C:\n\t\t\tfmt.Println("ТАЙМАУТ: Превышен лимит простоя потока!")\n\t\t\treturn\n\t\t}\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Обработка потока с защитой от утечек таймеров:\n#  -> Обработан элемент: 1 (таймер сброшен)\n#  -> Обработан элемент: 2 (таймер сброшен)\n#  -> Обработан элемент: 3 (таймер сброшен)\n#  -> Обработан элемент: 4 (таймер сброшен)\n# Поток успешно завершен!'}], 'under_the_hood': 'Сброс `timer.Reset()` переиспользует существующую структуру таймера в куче.', 'pitfalls': 'В Go 1.23+ поведение `time.Timer` улучшено (таймеры удаляются GC сразу после потери ссылок), но паттерн с `NewTimer` и `Reset` остается стандартом для HighLoad систем.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему перед вызовом timer.Reset(d) необходимо вызвать timer.Stop() и очистить timer.C?»\n**Ответ:** Чтобы исключить ложное мгновенное срабатывание таймера, если старый таймер уже успел отправить событие в буферизованный канал `timer.C` до вызова `Reset`.'}, {'num': 84, 'title': 'Выход из вложенного цикла select с помощью меток (Labeled Break)', 'task': '**[Каверзный кейс]**: Создай бесконечный цикл с `select`, который читает из двух каналов: `data` и `quit`. При получении сигнала в `quit`, выходи из цикла (используй `return` или `break` с меткой).', 'theory': 'Обычный оператор `break` внутри `select` прерывает только сам блок `select`, но не окружающий цикл `for`! Для выхода из цикла необходимо использовать `return` или `break LoopLabel` (Labeled Break).', 'step_by_step': '1. Создадим каналы `data` и `quit`.\n2. Зададим метку внешнего цикла `EventLoop: for { select { ... } }`.\n3. В ветке `case <-quit:` вызовем `break EventLoop`.\n4. Убедимся в полном выходе из цикла.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"time"\n)\n\nfunc main() {\n\tdata := make(chan int)\n\tquit := make(chan struct{})\n\n\tgo func() {\n\t\tdata <- 10\n\t\tdata <- 20\n\t\ttime.Sleep(10 * time.Millisecond)\n\t\tclose(quit) // Сигнал на выход\n\t}()\n\n\tfmt.Println("Запуск цикла EventLoop с Labeled Break:")\n\nEventLoop:\n\tfor {\n\t\tselect {\n\t\tcase v := <-data:\n\t\t\tfmt.Printf(" [Data] Обработано число: %d\\n", v)\n\t\tcase <-quit:\n\t\t\tfmt.Println(" [Quit] Получен сигнал quit -> выполняем break EventLoop")\n\t\t\tbreak EventLoop // ВЫХОДИТ ИЗ ЦИКЛА FOR, А НЕ ТОЛЬКО ИЗ SELECT!\n\t\t}\n\t}\n\n\tfmt.Println("Успешный выход за пределы цикла EventLoop!")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Запуск цикла EventLoop с Labeled Break:\n#  [Data] Обработано число: 10\n#  [Data] Обработано число: 20\n#  [Quit] Получен сигнал quit -> выполняем break EventLoop\n# Успешный выход за пределы цикла EventLoop!'}], 'under_the_hood': 'Компилятор Go связывает метку `EventLoop` с инструкцией `JMP` за пределы цикла `for`.', 'pitfalls': 'Написание простого `break` внутри `case` в бесконечном цикле — распространенный баг новичков, приводящий к вечному циклу.', 'bigtech_interview': '**Вопрос с собеседования:** «Что делает обычный оператор break внутри ветки select?»\n**Ответ:** Прерывает только блок `select`, передавая управление на следующую строку за `select`. Если `select` находился внутри `for`, начнется следующая итерация цикла.'}, {'num': 85, 'title': 'Реализация SLA-таймаута сетевой операции через time.After', 'task': 'Реализуйте таймаут операции: используйте `select` с каналом данных и каналом из `time.After()`. ', 'theory': 'Паттерн ограничения времени отклика (Response Deadline) защищает сервис от каскадной деградации пулов потоков.', 'step_by_step': '1. Создадим функцию имитации сетевого запроса.\n2. Ограничим время выполнения таймаутом 25 мс.\n3. Проверим перехват при превышении времени.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"time"\n)\n\nfunc executeRemoteCall(delay time.Duration) <-chan string {\n\tres := make(chan string, 1)\n\tgo func() {\n\t\ttime.Sleep(delay)\n\t\tres <- "HTTP 200 OK: payload_data"\n\t}()\n\treturn res\n}\n\nfunc main() {\n\t// Симулируем медленный внешний сервис (60 мс)\n\tresponseChan := executeRemoteCall(60 * time.Millisecond)\n\n\tfmt.Println("Отправка запроса с SLA таймаутом 25мс...")\n\n\tselect {\n\tcase payload := <-responseChan:\n\t\tfmt.Printf("Ответ получен вовремя: %s\\n", payload)\n\tcase <-time.After(25 * time.Millisecond):\n\t\tfmt.Println("ОШИБКА: Превышен SLA таймаут 25мс (Circuit Breaker Triggered)!")\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Отправка запроса с SLA таймаутом 25мс...\n# ОШИБКА: Превышен SLA таймаут 25мс (Circuit Breaker Triggered)!'}], 'under_the_hood': '`select` разблокируется строго в момент наступления первого из двух событий.', 'pitfalls': 'Всегда используйте буферизованный канал на 1 элемент в горутине задачи.', 'bigtech_interview': '**Вопрос с собеседования:** «Как комбинировать таймаут операции с отменой через context.Context?»\n**Ответ:** Передавать в `select` ветку `case <-ctx.Done(): return ctx.Err()`, используя контекст, созданный через `context.WithTimeout(parent, deadline)`.'}, {'num': 86, 'title': 'Периодический таймер: генерация тиков каждую секунду и контролируемый выход', 'task': 'Используй `time.Tick` для создания канала, который отправляет время каждую секунду. Выводи "tick" в консоль. Останови через 5 секунд.', 'theory': '`time.Tick` создает периодический таймер для фонового мониторинга и сбора метрик.', 'step_by_step': '1. Создадим канал тиков `ticker := time.Tick(10 * time.Millisecond)`.\n2. Создадим канал остановки `stop := time.After(45 * time.Millisecond)`.\n3. В цикле считываем тики и выводим `"tick"`.\n4. Штатно завершаем работу.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"time"\n)\n\nfunc main() {\n\tticks := time.Tick(10 * time.Millisecond)\n\tstop := time.After(45 * time.Millisecond)\n\n\tcount := 0\n\tfmt.Println("Запуск цикла периодических тиков:")\n\n\tfor {\n\t\tselect {\n\t\tcase <-ticks:\n\t\t\tcount++\n\t\t\tfmt.Printf(" -> tick #%d\\n", count)\n\t\tcase <-stop:\n\t\t\tfmt.Println("Интервал остановки достигнут! Завершение работы.")\n\t\t\treturn\n\t\t}\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Запуск цикла периодических тиков:\n#  -> tick #1\n#  -> tick #2\n#  -> tick #3\n#  -> tick #4\n# Интервал остановки достигнут! Завершение работы.'}], 'under_the_hood': 'Таймер генерирует события в фоне без задействования потоков ОС во время пауз.', 'pitfalls': 'В долгоживущих серверах используйте `time.NewTicker` с явным `defer ticker.Stop()`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в продакшене запрещают использовать time.Tick?»\n**Ответ:** Потому что сборщик мусора не может освободить память `time.Tick`, пока программа работает. При каждом вызове функции с `time.Tick` происходит утечка таймера.'}, {'num': 87, 'title': 'Периодический вывод системного времени через time.Tick и time.After', 'task': 'Создайте "тикущий" канал с помощью `time.Tick` и выведите текущее время каждые 500мс, прервав цикл через `time.After`.', 'theory': 'Форматирование временных меток в цикле мультиплексирования тикера и канала завершения.', 'step_by_step': '1. Создадим тикер `time.Tick(15 * time.Millisecond)`.\n2. Запустим цикл с форматированием времени.\n3. Прервем цикл через `time.After(50 * time.Millisecond)`.\n4. Проверим результат.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"time"\n)\n\nfunc main() {\n\ttickChan := time.Tick(15 * time.Millisecond)\n\tdeadlineChan := time.After(50 * time.Millisecond)\n\n\tfmt.Println("Служба точного времени запущена:")\n\n\tfor {\n\t\tselect {\n\t\tcase t := <-tickChan:\n\t\t\tfmt.Printf(" [CLOCK] Текущее время: %s\\n", t.Format("15:04:05.000"))\n\t\tcase <-deadlineChan:\n\t\t\tfmt.Println(" [CLOCK] Дедлайн истек, служба остановлена.")\n\t\t\treturn\n\t\t}\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Служба точного времени запущена:\n#  [CLOCK] Текущее время: 15:04:05.015\n#  [CLOCK] Текущее время: 15:04:05.030\n#  [CLOCK] Текущее время: 15:04:05.045\n#  [CLOCK] Дедлайн истек, служба остановлена.'}], 'under_the_hood': '`t.Format` форматирует метку времени без блокировок.', 'pitfalls': 'Используйте правильный шаблон форматирования даты в Go (`"2006-01-02 15:04:05"`).', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в Go шаблон форматирования времени строится вокруг даты 2006-01-02 15:04:05?»\n**Ответ:** Это мнемонический порядок чисел `1 2 3 4 5 6 7`: 1 (месяц 01), 2 (день 02), 3 (час 15/03), 4 (минуты 04), 5 (секунды 05), 6 (год 2006), 7 (таймзона MST).'}, {'num': 88, 'title': 'Псевдослучайное распределение выбора при одновременной готовности веток select', 'task': '**Каверзный случай**: Что произойдет, если в `select` указать несколько кейсов, которые готовы к выполнению одновременно? (Ответ: выбор случайный). Проверьте на практике.', 'theory': 'Экспериментальная валидация равновероятного выбора рантайма при одновременной готовности 2 веток.', 'step_by_step': '1. Создадим два буферизованных канала `ch1` и `ch2`.\n2. В цикле заполним оба канала и выполним `select`.\n3. Зафиксируем равное количество срабатываний.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n)\n\nfunc main() {\n\tch1 := make(chan int, 1)\n\tch2 := make(chan int, 1)\n\n\tc1Count, c2Count := 0, 0\n\tconst iterations = 1000\n\n\tfor i := 0; i < iterations; i++ {\n\t\tch1 <- 1\n\t\tch2 <- 2\n\n\t\tselect {\n\t\tcase <-ch1:\n\t\t\tc1Count++\n\t\t\t<-ch2\n\t\tcase <-ch2:\n\t\t\tc2Count++\n\t\t\t<-ch1\n\t\t}\n\t}\n\n\tfmt.Printf("Результаты 1000 одновременных гонок в select:\\n")\n\tfmt.Printf("Канал 1: %d раз (%.1f%%)\\n", c1Count, float64(c1Count)/float64(iterations)*100)\n\tfmt.Printf("Канал 2: %d раз (%.1f%%)\\n", c2Count, float64(c2Count)/float64(iterations)*100)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Результаты 1000 одновременных гонок в select:\n# Канал 1: 504 раз (50.4%)\n# Канал 2: 496 раз (49.6%)'}], 'under_the_hood': '`runtime.fastrand()` гарантирует распределение 50/50.', 'pitfalls': 'Никогда не используйте порядок веток `case` в качестве логического приоритета.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему псевдослучайный выбор в select делает программы на Go более надежными?»\n**Ответ:** Это предотвращает скрытые зависимости от порядка объявления каналов в коде и защищает распределенные алгоритмы от детерминированных тупиков синхронизации (Livelock).'}, {'num': 89, 'title': 'Защита долгих запросов к базе данных: Circuit Breaker Timeout в select', 'task': 'Напиши функцию, которая эмулирует долгий запрос к БД (sleep 2s) и возвращает результат через канал. В `main` используй `select`, чтобы дождаться либо результата, либо таймаута в 1 секунду (выведи "Request timed out").', 'theory': 'Паттерн Circuit Breaker / Timeout для SQL-запросов: если база данных перегружена и не отвечает в рамках SLA, клиент не блокирует свой пул горутин, а возвращает ошибку таймаута.', 'step_by_step': '1. Создадим функцию `executeSlowQuery() <-chan string`.\n2. Внутри выделим буферизованный канал `make(chan string, 1)` для исключения утечки горутины.\n3. В `main` дождемся ответа с таймаутом 30 мс.\n4. Выведем сообщение `"Request timed out"`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"time"\n)\n\nfunc executeSlowQuery() <-chan string {\n\tresChan := make(chan string, 1) // БУФЕР = 1 ИСКЛЮЧАЕТ GOROUTINE LEAK!\n\n\tgo func() {\n\t\ttime.Sleep(100 * time.Millisecond) // Симуляция долгой выборки SELECT * FROM big_table\n\t\tresChan <- "Rows: [User 1, User 2, User 3]"\n\t}()\n\n\treturn resChan\n}\n\nfunc main() {\n\tfmt.Println("[DB-Client] Запуск SQL-запроса...")\n\tqueryResult := executeSlowQuery()\n\n\tselect {\n\tcase result := <-queryResult:\n\t\tfmt.Printf("[DB-Client] Успешно получены данные: %s\\n", result)\n\tcase <-time.After(30 * time.Millisecond):\n\t\tfmt.Println("[DB-Client] Request timed out: База данных не ответила вовремя -> прерывание!")\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [DB-Client] Запуск SQL-запроса...\n# [DB-Client] Request timed out: База данных не ответила вовремя -> прерывание!'}], 'under_the_hood': '`make(chan string, 1)` позволяет фоновой горутине записать запоздавший ответ и корректно освободить память стека.', 'pitfalls': 'В реальных приложениях для отмены самого SQL-запроса на стороне СУБД используют `db.QueryContext(ctx, ...)`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему важно отменять сам SQL-запрос на сервере PostgreSQL/MySQL, а не только выходить по таймауту в Go?»\n**Ответ:** Если отменить ожидание только в Go, сервер БД продолжит сканировать диск и выполнять тяжелый JOIN, тратя IOPS и память СУБД впустую.'}, {'num': 90, 'title': 'Динамическое выключение веток в select через nil-канал', 'task': '**Каверзный случай**: Что произойдет, если использовать `nil`-канал (неинициализированный `var ch chan int`) в `select`? (Он блокируется навсегда). Используйте это знание, чтобы отключить ветку `select` динамически (обнулив канал).', 'theory': 'Практикум: динамическое отключение ветки `select` при обнаружении конца потока данных без разрушения общего цикла обработки.', 'step_by_step': '1. Создадим два канала источников.\n2. В цикле мультиплексирования считываем данные.\n3. При закрытии канала выставляем `ch = nil`.\n4. Цикл завершается, когда оба канала станут `nil`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n)\n\nfunc main() {\n\tprimaryChan := make(chan string)\n\tbackupChan := make(chan string)\n\n\tgo func() {\n\t\tprimaryChan <- "Первичные данные 1"\n\t\tclose(primaryChan)\n\t}()\n\n\tgo func() {\n\t\tbackupChan <- "Резервные данные 1"\n\t\tclose(backupChan)\n\t}()\n\n\tfor primaryChan != nil || backupChan != nil {\n\t\tselect {\n\t\tcase msg, ok := <-primaryChan:\n\t\t\tif !ok {\n\t\t\t\tfmt.Println("[Select] primaryChan закрыт -> отключаем ветку (primaryChan = nil)")\n\t\t\t\tprimaryChan = nil\n\t\t\t\tcontinue\n\t\t\t}\n\t\t\tfmt.Printf("Получено из primary: %s\\n", msg)\n\n\t\tcase msg, ok := <-backupChan:\n\t\t\tif !ok {\n\t\t\t\tfmt.Println("[Select] backupChan закрыт -> отключаем ветку (backupChan = nil)")\n\t\t\t\tbackupChan = nil\n\t\t\t\tcontinue\n\t\t\t}\n\t\t\tfmt.Printf("Получено из backup: %s\\n", msg)\n\t\t}\n\t}\n\n\tfmt.Println("Все потоки обработаны и динамически отключены!")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Получено из primary: Первичные данные 1\n# [Select] primaryChan закрыт -> отключаем ветку (primaryChan = nil)\n# Получено из backup: Резервные данные 1\n# [Select] backupChan закрыт -> отключаем ветку (backupChan = nil)\n# Все потоки обработаны и динамически отключены!'}], 'under_the_hood': '`nil`-канал навсегда блокирует свою ветку в `select`, что рантайм использует как сигнал пропуска.', 'pitfalls': 'Всегда проверяйте условие завершения цикла `for ch1 != nil || ch2 != nil`.', 'bigtech_interview': '**Вопрос с собеседования:** «Каковы 4 основных состояния канала в Go и их поведение?»\n**Ответ:** 1) `nil` — чтение/запись блокируют навсегда, закрытие $\\to$ паника. 2) `open & unbuffered` — синхронное рандеву. 3) `open & buffered` — неблокирующая запись до переполнения. 4) `closed` — чтение возвращает остаток буфера затем `zero value, ok=false`, запись и повторное закрытие $\\to$ паника.'}, {'num': 91, 'title': 'Доказательство псевдослучайного распределения веток select в Go', 'task': '**[Каверзный кейс]**: Если в `select` готовы сразу несколько `case`, какой выберет Go? Напиши программу, которая доказывает, что выбор случаен (random).', 'theory': 'Демонстрация генератора `fastrand()` внутри `runtime.selectgo`: при одновременной готовности 4 каналов частота выбора каждого канала стремится к $25\\% \\pm 2\\%.$', 'step_by_step': '1. Создадим 4 канала с буфером 1.\n2. В цикле 4000 раз заполним все 4 канала.\n3. Подсчитаем частоту срабатывания каждого case.\n4. Выведем проценты распределения.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n)\n\nfunc main() {\n\tc1 := make(chan int, 1)\n\tc2 := make(chan int, 1)\n\tc3 := make(chan int, 1)\n\tc4 := make(chan int, 1)\n\n\tcounts := make(map[string]int)\n\tconst total = 4000\n\n\tfor i := 0; i < total; i++ {\n\t\tc1 <- 1\n\t\tc2 <- 2\n\t\tc3 <- 3\n\t\tc4 <- 4\n\n\t\tselect {\n\t\tcase <-c1:\n\t\t\tcounts["Case 1"]++\n\t\t\t<-c2; <-c3; <-c4\n\t\tcase <-c2:\n\t\t\tcounts["Case 2"]++\n\t\t\t<-c1; <-c3; <-c4\n\t\tcase <-c3:\n\t\t\tcounts["Case 3"]++\n\t\t\t<-c1; <-c2; <-c4\n\t\tcase <-c4:\n\t\t\tcounts["Case 4"]++\n\t\t\t<-c1; <-c2; <-c3\n\t\t}\n\t}\n\n\tfmt.Println("=== Статистический тест случайности select (4 ветки) ===")\n\tfor k, v := range counts {\n\t\tfmt.Printf("%s: %d выборов (%.2f%%)\\n", k, v, float64(v)/float64(total)*100)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# === Статистический тест случайности select (4 ветки) ===\n# Case 1: 1002 выборов (25.05%)\n# Case 2:  994 выборов (24.85%)\n# Case 3: 1011 выборов (25.28%)\n# Case 4:  993 выборов (24.82%)'}], 'under_the_hood': '`fastrand()` инициализируется сидом горутины и не требует системных вызовов ядра ОС.', 'pitfalls': 'Случайный выбор не гарантирует строгого чередования 1-2-3-4 на микроинтервалах.', 'bigtech_interview': '**Вопрос с собеседования:** «Где в рантайме Go реализован случайный выбор select?»\n**Ответ:** В функции `runtime.selectgo` файла `src/runtime/select.go`: массив `pollorder` перемешивается алгоритмом Фишера-Йетса с использованием `fastrandn()`.'}, {'num': 92, 'title': 'Фатальная паника при попытке закрытия nil-канала (panic: close of nil channel)', 'task': '**Каверзный случай**: Что произойдет, если попытаться закрыть `nil`-канал? (Паника).', 'theory': 'Попытка вызова `close(ch)` на неинициализированном канале `nil` немедленно вызывает фатальную панику `panic: close of nil channel`.', 'step_by_step': '1. Создадим переменную `var nilChan chan int`.\n2. Вызовем `close(nilChan)` внутри защищенной функции `defer recover()`.\n3. Перехватим и проанализируем текст паники.\n4. Проверим корректность.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n)\n\nfunc safeCloseNilChannel() {\n\tdefer func() {\n\t\tif r := recover(); r != nil {\n\t\t\tfmt.Printf("Перехвачена критическая паника: %v\\n", r)\n\t\t}\n\t}()\n\n\tvar nilChan chan int\n\tfmt.Println("Попытка закрытия nil-канала: close(nilChan)...")\n\tclose(nilChan) // ВЫЗЫВАЕТ ПАНИКУ: close of nil channel\n}\n\nfunc main() {\n\tsafeCloseNilChannel()\n\tfmt.Println("Программа штатно продолжила работу после обработки паники.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Попытка закрытия nil-канала: close(nilChan)...\n# Перехвачена критическая паника: close of nil channel\n# Программа штатно продолжила работу после обработки паники.'}], 'under_the_hood': 'В функции `closechan` первой строкой выполняется проверка: `if c == nil { panic(plainError("close of nil channel")) }`.', 'pitfalls': 'Всегда проверяйте `if ch != nil { close(ch) }`, если канал может быть не инициализирован.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему close(nil) паникует, а чтение/запись на nil-канале блокируются?»\n**Ответ:** Блокировка чтения/записи на nil-канале необходима для работы динамического отключения веток в `select`. Закрытие же nil-канала не имеет никакого практического смысла и указывает на грубую ошибку инициализации структуры.'}, {'num': 93, 'title': 'Паттерн Drop Pattern: сброс избыточных сообщений при заполненном буфере', 'task': 'Используй `select` для отправки данных: если канал забит (буфер заполнен), срабатывает `default` (отбрасывание данных / drop pattern).', 'theory': 'Паттерн Drop Pattern (Отбрасывание пакетов) используется в системах телеметрии, метрик и стриминга видео: если приемник не справляется, свежие кадры или метрики отбрасываются, чтобы не создавать задержек (Lag).', 'step_by_step': '1. Создадим канал телеметрии `metrics := make(chan int, 2)`.\n2. Заполним буфер первыми двумя метриками.\n3. Попробуем отправить еще 2 метрики через `select default`.\n4. Зафиксируем безопасный сброс.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n)\n\ntype MetricsBuffer struct {\n\tch      chan int\n\tdropped int\n}\n\nfunc (m *MetricsBuffer) Push(val int) {\n\tselect {\n\tcase m.ch <- val:\n\t\tfmt.Printf("[METRICS] Записана метрика: %d\\n", val)\n\tdefault:\n\t\tm.dropped++\n\t\tfmt.Printf("[DROP PATTERN] Буфер переполнен! Метрика %d отброшена (всего сброшено: %d)\\n", val, m.dropped)\n\t}\n}\n\nfunc main() {\n\tbuf := &MetricsBuffer{\n\t\tch: make(chan int, 2),\n\t}\n\n\tbuf.Push(100)\n\tbuf.Push(200)\n\t// Буфер полон (2/2) -> следующие метрики отбрасываются\n\tbuf.Push(300)\n\tbuf.Push(400)\n\n\tfmt.Printf("\\nИтог: В буфере готово к обработке %d элементов, отброшено %d.\\n", len(buf.ch), buf.dropped)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [METRICS] Записана метрика: 100\n# [METRICS] Записана метрика: 200\n# [DROP PATTERN] Буфер переполнен! Метрика 300 отброшена (всего сброшено: 1)\n# [DROP PATTERN] Буфер переполнен! Метрика 400 отброшена (всего сброшено: 2)\n# \n# Итог: В буфере готово к обработке 2 элементов, отброшено 2.'}], 'under_the_hood': '`select default` на заполненном канале не аллоцирует структур и завершается мгновенно.', 'pitfalls': 'Не используйте Drop Pattern для финансовых транзакций или платежей — только для телеметрии и логов!', 'bigtech_interview': '**Вопрос с собеседования:** «Как реализовать неблокирующую отправку в канал с возвратом ошибки BufferOverflow?»\n**Ответ:** Через функцию `func Send(ch chan<- T, val T) error { select { case ch <- val: return nil default: return ErrBufferFull } }`.'}, {'num': 94, 'title': 'Паттерн Or-Done Channel: рекурсивное объединение N каналов отмены в один', 'task': 'Напишите функцию `or(done <-chan interface{}, channels ...<-chan interface{}) <-chan interface{}`, которая объединяет несколько каналов "сигналов завершения" в один (закрытие любого из них закрывает результирующий).', 'theory': 'Паттерн Or-Channel (или Or-Done) объединяет произвольное количество каналов отмены в единый канал: как только **любой** из входных каналов закрывается (или отправляет сигнал), результирующий канал мгновенно закрывается, отменяя всю операцию.', 'step_by_step': '1. Реализуем функцию `OrDone(channels ...<-chan struct{}) <-chan struct{}` с рекурсивным деревом или `select`.\n2. Создадим 3 канала отмены с разным временем срабатывания.\n3. Дождемся срабатывания самого быстрого канала.\n4. Проверим мгновенное закрытие результирующего канала.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"time"\n)\n\n// Паттерн Or-Channel: рекурсивное объединение каналов отмены\nfunc OrDone(channels ...<-chan struct{}) <-chan struct{} {\n\tswitch len(channels) {\n\tcase 0:\n\t\treturn nil\n\tcase 1:\n\t\treturn channels[0]\n\t}\n\n\torDone := make(chan struct{})\n\tgo func() {\n\t\tdefer close(orDone)\n\n\t\tswitch len(channels) {\n\t\tcase 2:\n\t\t\tselect {\n\t\t\tcase <-channels[0]:\n\t\t\tcase <-channels[1]:\n\t\t\t}\n\t\tdefault:\n\t\t\tselect {\n\t\t\tcase <-channels[0]:\n\t\t\tcase <-channels[1]:\n\t\t\tcase <-channels[2]:\n\t\t\tcase <-OrDone(append(channels[3:], orDone)...):\n\t\t\t}\n\t\t}\n\t}()\n\n\treturn orDone\n}\n\nfunc sigAfter(d time.Duration) <-chan struct{} {\n\tc := make(chan struct{})\n\tgo func() {\n\t\ttime.Sleep(d)\n\t\tclose(c)\n\t}()\n\treturn c\n}\n\nfunc main() {\n\tstart := time.Now()\n\n\t// 3 независимых источника отмены\n\tsig1 := sigAfter(100 * time.Millisecond)\n\tsig2 := sigAfter(25 * time.Millisecond) // Самый быстрый!\n\tsig3 := sigAfter(200 * time.Millisecond)\n\n\tfmt.Println("Ожидание первого сигнала через OrDone...")\n\n\t// Ждем закрытия любого из каналов\n\t<-OrDone(sig1, sig2, sig3)\n\n\tfmt.Printf("OrDone сработал через %v (сработал самый быстрый sig2)!\\n", time.Since(start).Round(time.Millisecond))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Ожидание первого сигнала через OrDone...\n# OrDone сработал через 25ms (сработал самый быстрый sig2)!'}], 'under_the_hood': 'Дерево рекурсивных `select` автоматически сворачивается при закрытии любого листа.', 'pitfalls': 'Для десятков каналов рекурсивный OrDone запускает $O(N)$ горутин. В Go 1.21+ для объединения отмен используют `context.WithCancelCause`.', 'bigtech_interview': '**Вопрос с собеседования:** «Какова практическая польза паттерна Or-Done?»\n**Ответ:** Он позволяет объединять отмену по HTTP-клиенту, отмену по таймауту базы данных и отмену по сигналу завершения процесса в один общий канал `done`.'}, {'num': 95, 'title': 'Паттерн Done Channel (Cancellation): широковещательная отмена N воркеров', 'task': 'Реализуйте паттерн "Done channel" (`done := make(chan struct{}); close(done)`), чтобы сигнализировать горутинам о необходимости завершения работы (Cancellation).', 'theory': 'Финальный комплексный паттерн главы: широковещательная отмена (Broadcast Cancellation) пула из $N$ воркеров через закрытие единого канала `close(done)` с гарантией завершения всех задач через `sync.WaitGroup`.', 'step_by_step': '1. Создадим `done := make(chan struct{})`.\n2. Запустим 3 параллельных воркера, слушающих `case <-done:`.\n3. В `main` вызовем `close(done)`.\n4. Дождемся завершения всех воркеров через `sync.WaitGroup`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\nfunc workerNode(id int, done <-chan struct{}, wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\tfmt.Printf("[Worker #%d] Воркер запущен и обрабатывает очередь...\\n", id)\n\n\tfor {\n\t\tselect {\n\t\tcase <-done: // Мгновенное широковещательное пробуждение при close(done)\n\t\t\tfmt.Printf(" -> [Worker #%d] Получен сигнал отмены done! Очистка и выход.\\n", id)\n\t\t\treturn\n\t\tdefault:\n\t\t\ttime.Sleep(10 * time.Millisecond)\n\t\t}\n\t}\n}\n\nfunc main() {\n\tdone := make(chan struct{})\n\tvar wg sync.WaitGroup\n\n\tconst totalWorkers = 3\n\twg.Add(totalWorkers)\n\n\tfor i := 1; i <= totalWorkers; i++ {\n\t\tgo workerNode(i, done, &wg)\n\t}\n\n\ttime.Sleep(25 * time.Millisecond)\n\n\tfmt.Println("\\n[Main] Отправка широковещательного сигнала отмены close(done)...")\n\tclose(done) // Разблокирует абсолютно ВСЕХ воркеров одновременно!\n\n\twg.Wait()\n\tfmt.Println("\\n[Main] Все 3 воркера успешно остановлены. Глава 21 освоена на 100%!")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# [Worker #1] Воркер запущен и обрабатывает очередь...\n# [Worker #2] Воркер запущен и обрабатывает очередь...\n# [Worker #3] Воркер запущен и обрабатывает очередь...\n# \n# [Main] Отправка широковещательного сигнала отмены close(done)...\n#  -> [Worker #1] Получен сигнал отмены done! Очистка и выход.\n#  -> [Worker #2] Получен сигнал отмены done! Очистка и выход.\n#  -> [Worker #3] Получен сигнал отмены done! Очистка и выход.\n# \n# [Main] Все 3 воркера успешно остановлены. Глава 21 освоена на 100%!'}], 'under_the_hood': '`close(done)` пробуждает все горутины из очереди `recvq` структуры `hchan` за один системный такт рантайма.', 'pitfalls': 'Никогда не отправляйте значения `done <- struct{}{}` в цикле для остановки $N$ воркеров — всегда используйте `close(done)`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему close(done) является фундаментальной основой пакета context в стандартной библиотеке Go?»\n**Ответ:** Потому что метод `ctx.Done()` возвращает канал `<-chan struct{}`, а вызов функции отмены `cancel()` просто закрывает этот канал (`close(c.done)`), мгновенно оповещая всех слушателей без необходимости знать их количество и адреса.'}]
